//! Load and render the sample documents (generated by tests/data/make_*.py).

use cb_office::{load, render_page, Effect, FontMap, Format, Renderer};
use cosmic_text::FontSystem;

fn data(name: &str) -> Vec<u8> {
    std::fs::read(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data").join(name)).unwrap()
}

#[test]
fn pptx_sample() {
    let mut fs = FontSystem::new();
    let mut map = FontMap::new();
    let doc = load(&data("sample.pptx"), Format::Pptx, &mut fs, &mut map).unwrap();
    assert_eq!(doc.pages.len(), 6);
    let p = &doc.pages[0];
    assert!((p.width - 960.0).abs() < 1.0 && (p.height - 540.0).abs() < 1.0);
    // Slide 5 has three click steps; the second flies in from the left.
    let s5 = &doc.pages[4];
    assert_eq!(s5.steps.len(), 3);
    assert!(matches!(s5.steps[1].effects[0].1, Effect::In { from } if from.0 < 0.0));
    assert_eq!(s5.hidden_after(0).len(), 3);
    assert_eq!(s5.hidden_after(3).len(), 0);
    // Table slide renders cell text and fills.
    let mut r = Renderer::new();
    for (i, page) in doc.pages.iter().enumerate() {
        let pm = render_page(&mut r, &mut fs, page, 0.5).unwrap();
        let non_white = pm.pixels().iter().filter(|c| c.red() < 240 || c.green() < 240 || c.blue() < 240).count();
        assert!(non_white > 200, "slide {} looks empty", i + 1);
    }
}

#[test]
fn docx_sample() {
    let mut fs = FontSystem::new();
    let mut map = FontMap::new();
    let doc = load(&data("sample.docx"), Format::Docx, &mut fs, &mut map).unwrap();
    // A page break plus long text: three A4/Letter pages.
    assert!(doc.pages.len() >= 3, "pages {}", doc.pages.len());
    assert!(doc.pages[0].width > 500.0 && doc.pages[0].height > 700.0);
    let mut r = Renderer::new();
    let pm = render_page(&mut r, &mut fs, &doc.pages[0], 0.5).unwrap();
    // The orange picture is on page 1.
    assert!(pm.pixels().iter().any(|c| c.red() > 200 && c.green() > 100 && c.green() < 140 && c.blue() < 60));
}

#[test]
fn rejects_garbage() {
    let mut fs = FontSystem::new();
    let mut map = FontMap::new();
    assert!(load(b"not a zip", Format::Pptx, &mut fs, &mut map).is_err());
    assert!(load(b"PK\x03\x04garbage", Format::Docx, &mut fs, &mut map).is_err());
}
